const letters = Array.from("hotel");
console.log(letters); // ["h","o","t","e","l"]

// The second argument maps each value while the array is built
const stars = Array.from({ length: 5 }, (unused, index) => index + 1);
console.log(stars); // [1,2,3,4,5]

// A Set has no indexes but it is iterable
const unique = Array.from(new Set(["a", "b", "a"]));
console.log(unique); // ["a","b"]

console.log(Array.isArray([1, 2]));        // true
console.log(Array.isArray({ length: 2 }));  // false, array-like but not an array
console.log(Array.isArray("abc"));          // false

// A common guard before array methods
function total(value) {
  if (!Array.isArray(value)) return 0;
  return value.reduce((sum, item) => sum + item, 0);
}

console.log(total([2, 3, 4])); // 9
console.log(total("2,3,4"));   // 0

const oneLevel = [1, [2, 3], [4, [5]]];
console.log(oneLevel.flat());     // [1,2,3,4,[5]]
console.log(oneLevel.flat(2));    // [1,2,3,4,5]
console.log(oneLevel.flat(Infinity)); // [1,2,3,4,5]

// Rows loaded from an API often nest one level too deep
const pages = [[{ id: 1 }, { id: 2 }], [{ id: 3 }]];
const hotels = pages.flat();
console.log(hotels.length); // 3

const bookings = [
  { hotel: "Danube View", guests: ["Anna", "Bela"] },
  { hotel: "City Loft", guests: ["Csilla"] }
];

// map would give an array of arrays, flatMap gives one flat list
const guests = bookings.flatMap((booking) => booking.guests);
console.log(guests); // ["Anna","Bela","Csilla"]

// Returning an empty array drops the item entirely
const onlyLong = bookings.flatMap((booking) =>
  booking.guests.length > 1 ? [booking.hotel] : []
);
console.log(onlyLong); // ["Danube View"]

const cities = ["Eger", "Budapest", "Gyor"];

console.log(cities.at(0));   // Eger
console.log(cities.at(-1));  // Gyor
console.log(cities.at(-2));  // Budapest

// Before at(), the last item was cities[cities.length - 1]
console.log(cities[cities.length - 1] === cities.at(-1)); // true

// Out of range returns undefined, it does not throw
console.log(cities.at(9)); // undefined

const numbers = [10, 2, 33, 4];

console.log([...numbers].sort());            // [10,2,33,4] as strings, wrong for numbers
console.log([...numbers].sort((a, b) => a - b)); // [2,4,10,33]

const hotels = [
  { name: "Danube View", stars: 4 },
  { name: "City Loft", stars: 5 },
  { name: "Lake Garden", stars: 3 }
];

// sort mutates, so copy first when the original order matters
const byStars = [...hotels].sort((a, b) => b.stars - a.stars);
console.log(byStars.map((hotel) => hotel.name)); // ["City Loft","Danube View","Lake Garden"]

const bookings = [
  { hotel_id: 1, adults: 2, children: 1 },
  { hotel_id: 2, adults: 2, children: 0 },
  { hotel_id: 1, adults: 1, children: 2 }
];

// Sum a field
const people = bookings.reduce(
  (sum, booking) => sum + booking.adults + booking.children,
  0
);
console.log(people); // 8

// Group into an object keyed by hotel_id
const byHotel = bookings.reduce((acc, booking) => {
  acc[booking.hotel_id] = (acc[booking.hotel_id] || 0) + 1;
  return acc;
}, {});
console.log(byHotel); // { "1": 2, "2": 1 }

const cities = ["Gyor", "Budapest", "Eger"];

const sorted = cities.toSorted();
console.log(sorted); // ["Budapest","Eger","Gyor"]
console.log(cities); // ["Gyor","Budapest","Eger"], unchanged

// toReversed and toSpliced follow the same copy rule
const reversed = cities.toReversed();
const withoutFirst = cities.toSpliced(0, 1);
console.log(reversed);      // ["Eger","Budapest","Gyor"]
console.log(withoutFirst);  // ["Budapest","Eger"]

const stars = { "Danube View": 4, "City Loft": 5, "Lake Garden": 3 };

for (const [name, value] of Object.entries(stars)) {
  console.log(name, value);
}

// Filter and rebuild an object from the pairs
const top = Object.fromEntries(
  Object.entries(stars).filter(([, value]) => value >= 4)
);
console.log(top); // { "Danube View": 4, "City Loft": 5 }

// Keys only, values only
console.log(Object.keys(stars).length); // 3
console.log(Object.values(stars));      // [4,5,3]

const pairs = [["name", "Danube View"], ["stars", 4], ["city", "Budapest"]];
console.log(Object.fromEntries(pairs));
// { name: "Danube View", stars: 4, city: "Budapest" }

// A Map converts in one call
const lookup = new Map([["HU", "Hungary"], ["AT", "Austria"]]);
console.log(Object.fromEntries(lookup)); // { HU: "Hungary", AT: "Austria" }

// Transform values while rebuilding
const doubled = Object.fromEntries(
  Object.entries({ a: 1, b: 2 }).map(([key, value]) => [key, value * 2])
);
console.log(doubled); // { a: 2, b: 4 }

const defaults = { stars: 3, city: "Budapest", breakfast: false };
const overrides = { stars: 5, breakfast: true };

// The first object is mutated, so pass a fresh one to keep defaults clean
const hotel = Object.assign({}, defaults, overrides);
console.log(hotel); // { stars: 5, city: "Budapest", breakfast: true }
console.log(defaults.stars); // 3, untouched

// The copy is shallow: nested objects are shared
const source = { rooms: { count: 10 } };
const clone = Object.assign({}, source);
clone.rooms.count = 99;
console.log(source.rooms.count); // 99, the nested object was shared

const hotels = [
  { name: "Danube View", city: "Budapest", stars: 4 },
  { name: "City Loft", city: "Budapest", stars: 5 },
  { name: "Valley Inn", city: "Eger", stars: 3 }
];

const byCity = Object.groupBy(hotels, (hotel) => hotel.city);
console.log(byCity.Budapest.length); // 2
console.log(byCity.Eger[0].name);    // Valley Inn

// Missing groups are absent, not empty arrays
console.log(byCity.Gyor); // undefined

// Map.groupBy does the same and keeps non-string keys intact
const byStars = Map.groupBy(hotels, (hotel) => hotel.stars);
console.log(byStars.get(5)[0].name); // City Loft

console.log("7".padStart(3, "0"));    // "007"
console.log("42".padStart(5, "*"));   // "***42"
console.log("abc".padStart(2, "0"));  // "abc", already long enough

// Fixed width invoice numbers
const numbers = [7, 42, 1234];
const lines = numbers.map((n) => String(n).padStart(6, "0"));
console.log(lines); // ["000007","000042","001234"]

// padEnd pads the other side
console.log("name".padEnd(10, ".")); // "name......"

const path = "hotels/2026/may/hotels.csv";

console.log(path.replace("/", "_"));      // hotels_2026/may/hotels.csv, first only
console.log(path.replaceAll("/", "_"));   // hotels_2026_may_hotels.csv

// A regular expression still works and adds patterns
console.log("a1 b2 c3".replaceAll(/\d/g, "#")); // "a# b# c#"

// The replacement can use $& for the whole match
console.log("cat".replaceAll("a", "[$&]")); // "c[a]t"

const code = "HU-2026";

console.log(code.at(0));   // "H"
console.log(code.at(-1));  // "6"
console.log(code.at(-4));  // "2"

// The bracket form returns undefined past the end, at() does too
console.log(code.at(99));  // undefined
console.log(code[99]);     // undefined

// charAt returns an empty string instead, which hides bugs
console.log(code.charAt(99) === ""); // true

const hotel = {
  name: "Danube View",
  stars: 4,
  owner_email: "owner@example.com",
  password: "not-for-json"
};

// An array of names keeps only those keys
const safe = JSON.stringify(hotel, ["name", "stars"]);
console.log(safe); // {"name":"Danube View","stars":4}

// A function replacer can transform values
const masked = JSON.stringify(hotel, (key, value) => {
  if (key === "password") return undefined; // undefined removes the key
  if (key === "owner_email") return "hidden";
  return value;
});
console.log(masked);

// The third argument sets indentation, here two spaces
console.log(JSON.stringify(hotel, ["name"], 2));

const text = '{"name":"Danube View","start_date":"2026-05-01","stars":4}';

// JSON has no date type, so dates arrive as strings
const plain = JSON.parse(text);
console.log(typeof plain.start_date); // "string"

// The reviver converts matching keys while parsing
const hotel = JSON.parse(text, (key, value) => {
  if (key === "start_date") return new Date(value + "T00:00:00Z");
  return value;
});
console.log(hotel.start_date instanceof Date); // true
console.log(hotel.start_date.getUTCFullYear()); // 2026

