const load = (url) =>
  url.includes("broken") ? Promise.reject(new Error("500")) : Promise.resolve(url);

const results = await Promise.allSettled([
  load("/api/hotels"),
  load("/broken"),
  load("/api/cities")
]);

console.log(results.map((result) => result.status));
// ["fulfilled","rejected","fulfilled"]

for (const result of results) {
  if (result.status === "fulfilled") console.log(result.value);
  else console.log(result.reason.message); // "500"
}

const slow = new Promise((resolve) => setTimeout(() => resolve("mirror-1"), 300));
const fast = new Promise((resolve) => setTimeout(() => resolve("mirror-2"), 100));
const dead = Promise.reject(new Error("offline"));

// The fastest success wins, even though one input fails
console.log(await Promise.any([slow, fast, dead])); // "mirror-2"

// All rejected gives an AggregateError with every reason
try {
  await Promise.any([Promise.reject(new Error("a")), Promise.reject(new Error("b"))]);
} catch (error) {
  console.log(error.name);          // "AggregateError"
  console.log(error.errors.length); // 2
}

const controller = new AbortController();

// A timeout cancels the request if the server is slow
const timer = setTimeout(() => controller.abort(), 2000);

try {
  const response = await fetch("/api/hotels", { signal: controller.signal });
  console.log(await response.json());
} catch (error) {
  if (error.name === "AbortError") console.log("Request cancelled");
  else console.log("Request failed", error);
} finally {
  clearTimeout(timer);
}

// abort() can carry a reason for the logs
controller.abort(new Error("user left the page"));

const price = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD"
});
console.log(price.format(1250)); // "$1,250.00"

// Percent takes a fraction, so 0.25 is 25%
const percent = new Intl.NumberFormat("en-US", {
  style: "percent",
  maximumFractionDigits: 0
});
console.log(percent.format(0.25)); // "25%"

// Plain grouping without decimals
const count = new Intl.NumberFormat("de-DE");
console.log(count.format(1234567)); // "1.234.567"

const date = new Date(Date.UTC(2026, 10, 11, 14, 30));

const medium = new Intl.DateTimeFormat("en-GB", {
  dateStyle: "medium",
  timeZone: "UTC"
});
console.log(medium.format(date)); // "11 Nov 2026"

// dateStyle and timeStyle cannot be mixed with year, month, day fields
const short = new Intl.DateTimeFormat("en-US", {
  dateStyle: "short",
  timeStyle: "short",
  timeZone: "UTC"
});
console.log(short.format(date)); // "11/11/26, 2:30 PM"

// formatToParts exposes each piece when you need one value
const parts = medium.formatToParts(date);
console.log(parts.find((part) => part.type === "year").value); // "2026"

const query = "city=Budapest&stars=4&city=Eger";

const params = new URLSearchParams(query);
console.log(params.get("city"));    // "Budapest", first value only
console.log(params.getAll("city")); // ["Budapest","Eger"]
console.log(params.has("stars"));   // true
console.log(params.get("missing")); // null

// Build a query string for fetch
const filters = new URLSearchParams();
filters.set("city", "Budapest");
filters.set("stars", "4");
console.log(filters.toString()); // "city=Budapest&stars=4"

console.log("/api/hotels?" + filters.toString());
